from __future__ import annotations

import os
from html import escape


def render_stable_founder_dashboard() -> str:
    email = escape(os.getenv("FOUNDER_EMAIL", "founder@ai-software-factory.local"))
    return HTML.replace("__EMAIL__", email)


HTML = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mission Control</title><style>body{margin:0;background:#06101f;color:#f2f7ff;font-family:Inter,system-ui,sans-serif}.login{min-height:100vh;display:grid;place-items:center}.card{background:#0b1628;border:1px solid #22314d;border-radius:20px;padding:28px;width:min(460px,90vw)}input,button,textarea{font:inherit}input,textarea{width:100%;box-sizing:border-box;margin:8px 0 14px;padding:12px;border-radius:10px;border:1px solid #22314d;background:#07101e;color:white}button{border:0;border-radius:10px;padding:12px 16px;background:linear-gradient(135deg,#3b82f6,#8b5cf6);color:white;font-weight:800}.app{display:none;grid-template-columns:240px 1fr;min-height:100vh}.side{background:#040c18;border-right:1px solid #22314d;padding:18px}.main{padding:22px}.nav button{display:block;width:100%;text-align:left;margin:6px 0;background:#13233d}.panel{border:1px solid #22314d;background:#0b1628;border-radius:16px;padding:18px;margin-bottom:14px}pre{white-space:pre-wrap;background:#050b15;border:1px solid #22314d;border-radius:12px;padding:12px}</style></head><body><section id="login" class="login"><div class="card"><h1>Platform Admin Login</h1><p>Sign in to enter Mission Control.</p><input id="email" value="__EMAIL__"><input id="pw" type="password" placeholder="Password"><button id="loginBtn">Enter Mission Control</button><p id="err"></p><p id="scriptStatus">Script loading...</p></div></section><section id="app" class="app"><aside class="side"><h2>AI Software Factory</h2><div class="nav"><button data-section="home">Home</button><button data-section="board">Board Room</button><button data-section="settings">Settings</button></div><button id="logoutBtn">Logout</button></aside><main class="main"><section id="home" class="panel"><h1>Mission Control Stable</h1><p>Hotfix dashboard restored.</p></section><section id="board" class="panel" style="display:none"><h1>Board Room</h1><textarea id="msg" placeholder="Ask Mission Control..."></textarea><p><button id="sendBtn">Send</button> <button id="proposalBtn">Create Proposal</button> <button id="runtimeBtn">Run Runtime Preview</button></p><pre id="out">Ready.</pre></section><section id="settings" class="panel" style="display:none"><h1>Settings</h1><p>Stable hotfix mode.</p></section></main></section><script>(function(){var token=localStorage.getItem('mission_control_token')||'';function id(x){return document.getElementById(x)}function app(){id('login').style.display='none';id('app').style.display='grid'}function log(){id('login').style.display='grid';id('app').style.display='none'}function post(u,b){return fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}).then(function(r){return r.json()})}function show(x){id('out').textContent=typeof x==='string'?x:JSON.stringify(x,null,2)}function sec(n){['home','board','settings'].forEach(function(s){id(s).style.display=s===n?'block':'none'})}async function signin(){try{var d=await post('/mission-control/auth/login',{email:id('email').value,password:id('pw').value});if(d.session&&d.session.token){token=d.session.token;localStorage.setItem('mission_control_token',token);app()}else{id('err').textContent=d.error||d.status||'Login failed'}}catch(e){id('err').textContent='Login failed: '+e}}document.addEventListener('DOMContentLoaded',function(){id('scriptStatus').textContent='Script ready';id('loginBtn').onclick=signin;id('pw').onkeydown=function(e){if(e.key==='Enter')signin()};id('logoutBtn').onclick=function(){localStorage.removeItem('mission_control_token');token='';log()};document.querySelectorAll('[data-section]').forEach(function(b){b.onclick=function(){sec(this.dataset.section)}});id('sendBtn').onclick=async function(){show('Thinking...');try{show(await post('/mission-control/operating-console/chat',{token:token,message:id('msg').value}))}catch(e){show('Request failed: '+e)}};id('proposalBtn').onclick=async function(){show('Creating proposal...');try{show(await post('/mission-control/operating-console/workflow',{token:token,action:'create-proposal',message:id('msg').value}))}catch(e){show('Request failed: '+e)}};id('runtimeBtn').onclick=async function(){show('Running preview...');try{show(await post('/platform/mission-runtime/run',{token:token,goal:id('msg').value||'Review Mission Control'}))}catch(e){show('Request failed: '+e)}};if(token){post('/mission-control/auth/session',{token:token}).then(function(d){d.authenticated?app():log()}).catch(log)}else{log()}})})();</script></body></html>
"""
